INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('URLs amigables', 'joomlaguide-sef-urls-es', '<p>Las URL amigables para motores de búsqueda (SEF) hacen que los enlaces de tu sitio sean cortos y legibles: Joomla las construye con los alias de tus elementos de menú y de tu contenido, en lugar de largas listas de parámetros.</p><p>En este recorrido activas las URL amigables en la Configuración global. Este playground empieza con ellas desactivadas, para que veas la diferencia.</p><p>Antes de empezar, mira tu sitio: haz clic en el botón con el nombre de tu sitio, arriba en la cabecera (en el Joomla Playground también puedes hacer clic en <strong>Site</strong> en su barra). Haz clic en <strong>Quiénes somos</strong> en el menú y mira la dirección: algo como <code>index.php?option=com_content&amp;view=article&amp;id=1&amp;Itemid=102</code>.</p><p>Este recorrido sigue el tutorial <a href="https://guide.joomla.org/es/tutoriales/gestion-de-contenido/8-urls/8-1-urls-amigables" target="_blank" rel="noopener">8.1 URLs amigables</a> de la Guía del usuario de Joomla.</p>', 1, '["com_cpanel","com_config"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 8.1 SEF URLs', 1, 1);
